    public static bool TryGet(string languageCode, string appName, out string localizedName)
    {
        localizedName = string.Empty;
        return Names.TryGetValue(languageCode, out var names) &&
               names.TryGetValue(appName, out localizedName!);
    }

    public static bool TryGetMap(string languageCode, out IReadOnlyDictionary<string, string>? names) =>
        Names.TryGetValue(languageCode, out names);

    private static IReadOnlyDictionary<string, string> CreateAppNames(params (string Original, string Localized)[] names) =>
        names.ToDictionary(name => name.Original, name => name.Localized, StringComparer.OrdinalIgnoreCase);
